<?php
function qa_obec_table_ready(){static $r=null;if($r!==null)return $r;$db=qa_db();foreach(array('qa_obec_subactivities','qa_project_obec_subactivity_links','qa_obec_workload_records') as $t){$q=$db->query("SHOW TABLES LIKE '".$db->real_escape_string($t)."'");if(!$q||$q->num_rows<1){if($q)$q->free();return $r=false;}$q->free();}return $r=true;}
function qa_obec_subactivities($activeOnly=true){if(!qa_obec_table_ready())return array();$db=qa_db();$rows=array();$sql="SELECT s.*,d.division_code,d.division_name FROM qa_obec_subactivities s LEFT JOIN qa_divisions d ON d.division_id=s.default_division_id".($activeOnly?" WHERE s.is_active=1":"")." ORDER BY s.sort_order,s.subactivity_code";$q=$db->query($sql);if($q){while($x=$q->fetch_assoc())$rows[]=$x;$q->free();}return $rows;}
function qa_obec_project_subactivity($pid){if(!qa_obec_table_ready())return null;$db=qa_db();$st=$db->prepare("SELECT s.*,d.division_code,d.division_name FROM qa_project_obec_subactivity_links l INNER JOIN qa_obec_subactivities s ON s.subactivity_id=l.subactivity_id LEFT JOIN qa_divisions d ON d.division_id=s.default_division_id WHERE l.project_id=? LIMIT 1");$st->bind_param('i',$pid);$st->execute();$q=$st->get_result();$r=$q?$q->fetch_assoc():null;if($q)$q->free();$st->close();return $r;}
function qa_obec_project_subactivity_id($pid){$r=qa_obec_project_subactivity($pid);return $r?(int)$r['subactivity_id']:0;}
function qa_obec_valid_subactivity($sid){if(!qa_obec_table_ready()||(int)$sid<=0)return false;$db=qa_db();$st=$db->prepare("SELECT COUNT(*) FROM qa_obec_subactivities WHERE subactivity_id=? AND is_active=1");$st->bind_param('i',$sid);$st->execute();$st->bind_result($n);$st->fetch();$st->close();return (int)$n>0;}
function qa_obec_save_project_subactivity($pid,$sid){if(!qa_obec_table_ready())return false;$db=qa_db();$pid=(int)$pid;$sid=(int)$sid;if(!$db->query("DELETE FROM qa_project_obec_subactivity_links WHERE project_id=".$pid))return false;if($sid<=0)return true;$st=$db->prepare("INSERT INTO qa_project_obec_subactivity_links(project_id,subactivity_id) VALUES (?,?)");$st->bind_param('ii',$pid,$sid);$ok=$st->execute();$st->close();return $ok;}
function qa_obec_can_manage_workload(){return qa_user_can('obec.manage');}
function qa_obec_workload_auto_count($year,$sid){if(!qa_obec_table_ready())return 0;return (int)qa_db_scalar("SELECT COUNT(*) FROM qa_project_obec_subactivity_links l INNER JOIN qa_projects p ON p.project_id=l.project_id WHERE p.year_id=".(int)$year." AND l.subactivity_id=".(int)$sid." AND p.status_code NOT IN ('DRAFT','REJECTED','CANCELLED')",0);}
function qa_obec_workload_record($year,$sid){if(!qa_obec_table_ready())return null;$db=qa_db();$st=$db->prepare("SELECT * FROM qa_obec_workload_records WHERE year_id=? AND subactivity_id=? LIMIT 1");$st->bind_param('ii',$year,$sid);$st->execute();$q=$st->get_result();$r=$q?$q->fetch_assoc():null;if($q)$q->free();$st->close();return $r;}
function qa_obec_change_info($prev,$cur){$prev=(int)$prev;$cur=(int)$cur;if($prev===0){if($cur===0)return array('pct'=>0,'requires_reason'=>false,'label'=>'0.00%');return array('pct'=>null,'requires_reason'=>true,'label'=>'เพิ่มจาก 0');}$p=(($cur-$prev)/$prev)*100;return array('pct'=>$p,'requires_reason'=>abs($p)>20.000001,'label'=>($p>0?'+':'').number_format($p,2).'%');}
